#!/usr/bin/env python3
"""Install frozen E23 M-family replay-router v1 into the Kaggle repository."""

from __future__ import annotations

from datetime import datetime
from pathlib import Path
import base64
import hashlib
import textwrap
import zlib

ROOT = Path(__file__).resolve().parent
BUNDLE = ROOT / "artifacts" / "bundles" / "current"
TARGET = BUNDLE / "agent_e23_m_family_v1.py"
EXP_DIR = ROOT / "experiments" / "e023_m_family_v1"
README = EXP_DIR / "README.md"
INDEX = ROOT / "docs" / "experiment_index.md"
HISTORY = ROOT / "EXPERIMENT_RUN_HISTORY.md"

AGENT_B64 = """"""
EXPECTED_SHA = "407a19a6db3109c5c7e5648bdc668284f06493fdb16f0cf1b0d7cc2a5ea3b6db"


def main():
    print("=== Install E23: M-family replay-router v1 ===")
    print("Repository root:", ROOT)

    if not BUNDLE.exists():
        raise SystemExit("Run this from the Kaggle repository root.")

    agent_text = zlib.decompress(base64.b64decode(AGENT_B64)).decode("utf-8")
    compile(agent_text, str(TARGET), "exec")

    actual = hashlib.sha256(agent_text.encode("utf-8")).hexdigest()
    if actual != EXPECTED_SHA:
        raise SystemExit(f"Embedded E23 hash mismatch: {actual} != {EXPECTED_SHA}")

    TARGET.write_text(agent_text, encoding="utf-8")

    EXP_DIR.mkdir(parents=True, exist_ok=True)
    README.write_text(
        textwrap.dedent(f"""\
        # E23 — M-family replay-router v1

        E23 is the first candidate intentionally outside the E21/E22 K-line production family.

        It contains a 24-route library derived from public 2026-09-18 Kaggriculture replay
        behavior from Majkel1337 and Arda Ceylan, with:
        - standardized M-family hand counts;
        - land retry from step 150 and step 220;
        - route reselection at shop unlocks;
        - unit-position-aware hand remapping;
        - runtime validity repairs.

        It embeds public replay behavior only, not competitor source code.

        SHA256: `{actual}`
        """),
        encoding="utf-8",
    )

    if INDEX.exists():
        txt = INDEX.read_text(encoding="utf-8")
        if "| E23 |" not in txt:
            row = (
                "| E23 | M-family replay-router v1 (24 replay-derived routes) | "
                "`artifacts/bundles/current/agent_e23_m_family_v1.py` | "
                "fresh screening pending | independent M-family candidate | "
                "4H/2C3S; step150/220 land; shop-prefix routing |\\n"
            )
            marker = "\\n## Legacy non-E series"
            if marker in txt:
                txt = txt.replace(marker, "\\n" + row + marker)
            else:
                txt = txt.rstrip() + "\\n" + row
            INDEX.write_text(txt, encoding="utf-8")

    now = datetime.now().astimezone().isoformat(timespec="seconds")
    if not HISTORY.exists():
        HISTORY.write_text("# Experiment Run History\\n\\n", encoding="utf-8")

    with HISTORY.open("a", encoding="utf-8") as f:
        f.write(
            f"## {now} — Install E23 M-family replay-router v1\\n\\n"
            f"- Agent: `{TARGET.relative_to(ROOT)}`\\n"
            f"- SHA256: `{actual}`\\n"
            "- Route library: 24 public-replay-derived Majkel1337/Arda Ceylan routes.\\n"
            "- No competitor source code embedded.\\n"
            "- No Kaggle submission performed.\\n\\n"
        )

    print("Wrote:", TARGET.relative_to(ROOT))
    print("SHA256:", actual)
    print("Wrote:", README.relative_to(ROOT))
    print("=== E23 install complete ===")


if __name__ == "__main__":
    main()
